import re

# MAJOR.MINOR.PATCH, non-negative integers without leading zeros.
_VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")

# type[(scope)][!]: text
# type: lower-case letters. scope: anything but parentheses, not empty.
# Exactly one space after the colon, then non-empty text starting with a non-space.
_HEADER = re.compile(r"([a-z]+)(?:\(([^()]+)\))?(!)?: (\S.*)")

_FOOTER_PREFIXES = ("BREAKING CHANGE: ", "BREAKING-CHANGE: ")


def _parse_version(current):
    if not isinstance(current, str):
        raise ValueError(f"not a version: {current!r}")
    m = _VERSION.fullmatch(current)
    if m is None:
        raise ValueError(f"not a version: {current!r}")
    return tuple(int(part) for part in m.groups())


def _classify(message):
    """Return (kind, breaking) for one commit message; kind is 'feat', 'fix', 'other' or None if no valid header."""
    lines = str(message).splitlines()
    if not lines:
        return None, False
    m = _HEADER.fullmatch(lines[0])
    if m is None:
        return None, False
    ctype, _scope, bang, _text = m.groups()
    breaking = bang == "!" or any(
        line.startswith(_FOOTER_PREFIXES) for line in lines[1:]
    )
    if ctype == "feat":
        kind = "feat"
    elif ctype == "fix":
        kind = "fix"
    else:
        kind = "other"
    return kind, breaking


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    major, minor, patch = _parse_version(current)

    any_breaking = False
    any_feat = False
    any_fix = False
    for message in commits:
        kind, breaking = _classify(message)
        if kind is None:
            continue
        any_breaking = any_breaking or breaking
        any_feat = any_feat or kind == "feat"
        any_fix = any_fix or kind == "fix"

    if any_breaking:
        if major >= 1:
            return f"{major + 1}.0.0"
        return f"0.{minor + 1}.0"
    if any_feat:
        if major >= 1:
            return f"{major}.{minor + 1}.0"
        return f"0.{minor}.{patch + 1}"
    if any_fix:
        return f"{major}.{minor}.{patch + 1}"
    return current
